@'
:root {
  --bg: #0f141c;
  --bg-2: #151c28;
  --bg-3: #1c2534;
  --border: #2b3648;
  --text: #e6edf6;
  --text-dim: #93a1b5;
  --accent: #5aa9ff;
  --accent-2: #7ee0c1;
  --up: #f2c14e;
  --down: #5aa9ff;
  --cycle: #e879a6;
  --danger: #ff6b6b;
  --ok: #4cd07d;
  --node: #26344a;
  --node-stroke: #3d5272;
  font-size: 14px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  background: var(--bg);
  color: var(--text);
  font-family: "Cascadia Code", "JetBrains Mono", Consolas, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
}

body { display: flex; flex-direction: column; overflow: hidden; }

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 18px;
  background: var(--bg-2);
  border-bottom: 1px solid var(--border);
  flex: 0 0 auto;
}
.brand { display: flex; align-items: center; gap: 12px; }
.logo {
  font-size: 26px;
  color: var(--accent);
  background: var(--bg-3);
  width: 38px; height: 38px;
  display: grid; place-items: center;
  border-radius: 8px;
  border: 1px solid var(--border);
}
.brand h1 { font-size: 16px; margin: 0; letter-spacing: .5px; }
.sub { margin: 2px 0 0; font-size: 12px; color: var(--text-dim); }

.actions { display: flex; gap: 8px; }
button {
  background: var(--bg-3);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 7px;
  padding: 7px 14px;
  cursor: pointer;
  font-size: 13px;
  font-family: inherit;
  transition: background .12s, border-color .12s, transform .05s;
}
button:hover { background: #243146; border-color: #44577a; }
button:active { transform: translateY(1px); }
button.primary { background: #1d4ed8; border-color: #2f6be0; font-weight: 600; }
button.primary:hover { background: #2459e6; }
button.ghost { background: transparent; color: var(--accent-2); }

.layout {
  flex: 1 1 auto;
  display: grid;
  grid-template-columns: minmax(340px, 42%) 1fr;
  gap: 12px;
  padding: 12px;
  min-height: 0;
}

.pane {
  background: var(--bg-2);
  border: 1px solid var(--border);
  border-radius: 10px;
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
}
.pane-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border);
  flex: 0 0 auto;
}
.pane-head h2 { margin: 0; font-size: 14px; }
.pane-foot {
  padding: 8px 14px;
  border-top: 1px solid var(--border);
  flex: 0 0 auto;
}
.hint { color: var(--text-dim); font-size: 12px; }
code {
  background: var(--bg-3);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 0 4px;
  font-size: 11px;
  color: var(--accent-2);
}

#input {
  flex: 1 1 auto;
  width: 100%;
  resize: none;
  border: none;
  outline: none;
  background: transparent;
  color: var(--text);
  padding: 12px 14px;
  font-family: inherit;
  font-size: 13px;
  line-height: 1.7;
  min-height: 0;
}

.pane-left { position: relative; }
.drop-overlay {
  position: absolute;
  inset: 0;
  background: rgba(29, 78, 216, .18);
  border: 2px dashed var(--accent);
  border-radius: 10px;
  display: grid;
  place-items: center;
  font-size: 18px;
  color: var(--accent);
  font-weight: 600;
  pointer-events: none;
  z-index: 5;
}
.hidden { display: none !important; }

.stats { display: flex; gap: 14px; font-size: 12px; color: var(--text-dim); flex-wrap: wrap; justify-content: flex-end; }
.stats b { color: var(--text); }
.stats .bad { color: var(--cycle); }
.stats .good { color: var(--ok); }

.tabs { display: flex; gap: 4px; padding: 8px 10px 0; border-bottom: 1px solid var(--border); flex: 0 0 auto; }
.tab {
  background: transparent;
  border: 1px solid transparent;
  border-bottom: none;
  border-radius: 7px 7px 0 0;
  color: var(--text-dim);
  padding: 7px 14px;
}
.tab:hover { background: var(--bg-3); }
.tab.active { color: var(--text); background: var(--bg-3); border-color: var(--border); position: relative; }
.tab-panel { display: none; flex: 1 1 auto; min-height: 0; overflow: auto; position: relative; }
.tab-panel.active { display: block; }

#tab-graph { display: none; flex-direction: column; }
#tab-graph.active { display: flex; }

.graph-wrap { flex: 1 1 auto; position: relative; overflow: auto; min-height: 200px; }
#graph-canvas { padding: 22px; min-width: 100%; }
.empty-hint {
  color: var(--text-dim);
  text-align: center;
  padding: 48px 20px;
  line-height: 2;
  font-size: 13px;
}

.selection-info {
  flex: 0 0 auto;
  border-top: 1px solid var(--border);
  padding: 8px 14px;
  min-height: 36px;
  font-size: 12px;
  line-height: 1.7;
}
.sel-row { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }
.chip {
  display: inline-block;
  padding: 1px 8px;
  border-radius: 999px;
  font-size: 11px;
  border: 1px solid var(--border);
  background: var(--bg-3);
}
.chip.up { color: var(--up); border-color: rgba(242,193,78,.4); }
.chip.down { color: var(--down); border-color: rgba(90,169,255,.4); }
.chip.cycle { color: var(--cycle); border-color: rgba(232,121,166,.4); }

.cycle-pop {
  position: absolute;
  right: 16px;
  top: 48px;
  width: min(480px, 90%);
  max-height: 60%;
  background: var(--bg-3);
  border: 1px solid var(--cycle);
  border-radius: 10px;
  box-shadow: 0 12px 40px rgba(0,0,0,.5);
  z-index: 20;
  display: flex;
  flex-direction: column;
}
.cycle-pop-head { display: flex; justify-content: space-between; align-items: center; padding: 8px 12px; border-bottom: 1px solid var(--border); }
.cycle-pop-head button { padding: 2px 9px; }
.cycle-pop-body { overflow: auto; padding: 8px 12px; }

.cycle-line {
  font-size: 12px;
  padding: 5px 8px;
  border-radius: 6px;
  cursor: pointer;
  line-height: 1.6;
  color: var(--text);
}
.cycle-line:hover { background: #26344d; }
.cycle-line.ringing { background: rgba(232,121,166,.18); }
.cycle-line .idx { color: var(--text-dim); margin-right: 8px; }
.cycle-line .arrow { color: var(--cycle); }

.topo-list, .cycle-list, .isolate-list { padding: 14px; }
.topo-layer { margin-bottom: 14px; }
.topo-layer h3 {
  margin: 0 0 8px;
  font-size: 12px;
  color: var(--accent-2);
  font-weight: 600;
}
.topo-items { display: flex; flex-wrap: wrap; gap: 6px; }
.topo-item {
  background: var(--bg-3);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 3px 10px;
  font-size: 12px;
  cursor: pointer;
}
.topo-item.group { border-color: rgba(232,121,166,.55); color: #f2a8c8; }
.topo-item.isolate { border-style: dashed; color: var(--text-dim); }
.topo-item:hover { background: #26344d; }
.topo-order { color: var(--text-dim); font-size: 11px; margin-right: 6px; }

.cycle-summary {
  background: var(--bg-3);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 10px 14px;
  margin-bottom: 12px;
  font-size: 13px;
  line-height: 1.9;
}
.cycle-summary .n { color: var(--cycle); font-weight: 700; font-size: 16px; }
.cycle-entry {
  border: 1px solid var(--border);
  border-radius: 8px;
  margin-bottom: 8px;
  overflow: hidden;
}
.cycle-entry-head {
  display: flex;
  justify-content: space-between;
  padding: 8px 12px;
  background: var(--bg-3);
  cursor: pointer;
  font-size: 13px;
}
.cycle-entry-head .tag { color: var(--cycle); }
.cycle-entry-body { padding: 6px 12px 10px; }
.cycle-more {
  width: 100%;
  margin-top: 6px;
  text-align: center;
  color: var(--accent);
  font-size: 12px;
}

.isolate-zone {
  border: 1px dashed var(--border);
  border-radius: 8px;
  padding: 12px 14px;
  margin-bottom: 12px;
}
.isolate-zone h3 { margin: 0 0 8px; font-size: 13px; }
.isolate-zone p { margin: 4px 0; font-size: 12px; color: var(--text-dim); }
.isolate-names { display: flex; flex-wrap: wrap; gap: 6px; }
.isolate-name {
  border: 1px dashed var(--node-stroke);
  border-radius: 6px;
  padding: 2px 10px;
  font-size: 12px;
  color: var(--text-dim);
}

.test-toolbar { display: flex; align-items: center; gap: 14px; padding: 10px 14px; border-bottom: 1px solid var(--border); }
.test-output { padding: 12px 14px; font-size: 12.5px; line-height: 1.7; }
.test-case { padding: 6px 8px; border-bottom: 1px solid rgba(43,54,72,.5); }
.test-case .status { font-weight: 700; margin-right: 8px; }
.test-case.pass .status { color: var(--ok); }
.test-case.fail .status { color: var(--danger); }
.test-case .name { color: var(--text); }
.test-detail { margin: 6px 0 2px 22px; color: var(--text-dim); white-space: pre-wrap; }
.test-detail .expected { color: var(--ok); }
.test-detail .actual { color: var(--danger); }
.test-banner { padding: 8px; border-radius: 7px; margin-bottom: 10px; font-weight: 600; }
.test-banner.pass { background: rgba(76,208,125,.12); border: 1px solid rgba(76,208,125,.4); color: var(--ok); }
.test-banner.fail { background: rgba(255,107,107,.12); border: 1px solid rgba(255,107,107,.4); color: var(--danger); }

/* SVG graph styles */
.dep-node { cursor: pointer; }
.dep-node rect { fill: var(--node); stroke: var(--node-stroke); stroke-width: 1.2; transition: fill .12s, stroke .12s; }
.dep-node text { fill: var(--text); font-size: 12px; pointer-events: none; dominant-baseline: central; }
.dep-node:hover rect { stroke: var(--accent); }
.dep-node.dim rect, .dep-node.dim text { opacity: .22; }
