.dep-node.selected rect { stroke: #fff; stroke-width: 2.4; }
.dep-node.self rect { fill: #3d2233; stroke: var(--cycle); }
.dep-node.self text { fill: #f7b9d4; }

.edge { fill: none; stroke: #46586f; stroke-width: 1.3; opacity: .55; }
