      return m;
    }
    defs.appendChild(marker('arr-normal', C.edge));
    defs.appendChild(marker('arr-up', C.up));
    defs.appendChild(marker('arr-down', C.down));
    defs.appendChild(marker('arr-in', C.inCycle));
    svg.appendChild(defs);

