const http = require('http');
const fs = require('fs');
const path = require('path');
http.createServer((req, res) => {
  let u = decodeURIComponent(req.url.split('?')[0]);
  if (u === '/') u = '/index.html';
  const fp = path.join(__dirname, u);
  fs.readFile(fp, (e, d) => {
    if (e) { res.statusCode = 404; res.end('not found'); return; }
    const ext = String(fp.match(/\.[a-z]+$/) || [''])[0];
    const t = ext === '.css' ? 'text/css' : ext === '.js' ? 'text/javascript' : 'text/html';
    res.setHeader('Content-Type', t + '; charset=utf-8');
    res.end(d);
  });
}).listen(8731, () => console.log('serving on 8731'));
