const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1500, height: 950 } });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  await page.goto('http://localhost:8731/', { waitUntil: 'networkidle' });
  await page.click('#btn-load-sample');
  await page.waitForTimeout(300);
  const stats = await page.$eval('#stats', e => e.textContent.replace(/\s+/g, ' ').trim());
  const svgCount = await page.$$eval('#graph-canvas svg', els => els.length);
  const nodeCount = await page.$$eval('#graph-canvas [data-node]', els => els.length);
  const groups = await page.$$eval('#graph-canvas .comp-group', els => els.length);
  console.log('stats:', stats);
  console.log('svg:', svgCount, 'nodes:', nodeCount, 'groups:', groups);
  await page.screenshot({ path: '_shot1.png', fullPage: false });

  // 点击 logger（在环里），检查闭包信息与高亮
  const names = await page.$$eval('#graph-canvas [data-node]', els => els.map(e => e.dataset.node));
  console.log('sample nodes:', names.slice(0, 20).join(','));
  if (names.includes('logger')) {
    await page.click('#graph-canvas [data-node="logger"] rect');
    await page.waitForTimeout(150);
    const info = await page.$eval('#selection-info', e => e.textContent.replace(/\s+/g, ' ').trim());
    console.log('logger closure:', info);
    await page.screenshot({ path: '_shot2.png' });
  }

  // 拓扑顺序 & 环清单文本
  await page.click('.tab[data-tab="tab-topo"]');
  const topo = await page.$eval('#topo-list', e => e.textContent.replace(/\s+/g, ' ').trim().slice(0, 300));
  console.log('topo:', topo);
  await page.click('.tab[data-tab="tab-cycles"]');
  const cyc = await page.$eval('#cycle-list', e => e.textContent.replace(/\s+/g, ' ').trim().slice(0, 300));
  console.log('cycles:', cyc);
  await page.click('.tab[data-tab="tab-isolates"]');
  const iso = await page.$eval('#isolate-list', e => e.textContent.replace(/\s+/g, ' ').trim());
  console.log('isolates:', iso);

  // 运行自测
  await page.click('#btn-selftest');
  await page.waitForTimeout(600);
  const summary = await page.$eval('#test-summary', e => e.textContent.trim());
  const fails = await page.$$eval('#test-output .test-case.fail', els => els.map(e => e.textContent.replace(/\s+/g,' ').trim()));
  console.log('selftest:', summary, 'fails:', fails.length);
  fails.forEach(f => console.log('  FAIL:', f.slice(0, 200)));
  console.log('js errors:', errors.length ? errors.join('\n') : 'none');
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(2); });
'@; node _ui_check.js"}

