const { chromium } = require('C:/Users/28973/npm-global/node_modules/openclaw/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1500, height: 950 } });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  await page.goto('http://localhost:8731/', { waitUntil: 'networkidle' });
  await page.click('#btn-load-sample');
  await page.waitForTimeout(200);
  await page.screenshot({ path: '_shot1.png' });

  await page.click('#graph-canvas g[data-node="logger"]');
  await page.waitForTimeout(150);
  await page.screenshot({ path: '_shot2.png' });
  // 统计被高亮的节点分类
  const hl = await page.evaluate(() => {
    const out = { up: [], down: [], group: [], dim: 0 };
    document.querySelectorAll('#graph-canvas g[data-node]').forEach(g => {
      const op = g.getAttribute('opacity');
      const n = g.dataset.node;
      if (g.dataset.hl === 'up') out.up.push(n);
      else if (g.dataset.hl === 'down') out.down.push(n);
      else if (g.dataset.hl === 'group') out.group.push(n);
      else if (op && Number(op) < 0.5) out.dim++;
    });
    out.up.sort(); out.down.sort(); out.group.sort();
    return out;
  });
  console.log('highlight:', JSON.stringify(hl));

  // 点背景清除
  await page.click('#graph-canvas svg', { position: { x: 5, y: 5 } });
  await page.waitForTimeout(100);

  // 点击循环组标题 → 弹窗
  await page.click('#graph-canvas .group-label');
  await page.waitForTimeout(150);
  const popVisible = await page.$eval('#cycle-pop', e => !e.classList.contains('hidden'));
  const popTitle = await page.$eval('#cycle-pop-title', e => e.textContent);
  console.log('cycle pop:', popVisible, popTitle);
  // 点弹窗里第一条环 → 图上高亮
  await page.click('#cycle-pop-body .cycle-line');
  await page.waitForTimeout(150);
  const goldCount = await page.$$eval('#graph-canvas [data-node] rect', rects =>
    rects.filter(r => r.getAttribute('stroke') === '#ffd166').length);
  console.log('gold highlighted nodes:', goldCount);
  await page.screenshot({ path: '_shot3.png' });

  // 超脏数据自由输入：混乱箭头/引号/重复/注释
  const dirty = [
    '## build graph',
    '  "svc-a"  =>  db , cache ;  ',
    'svc-a depends on auth',
    'svc-a -> db        // dup below',
    'svc-a:db',
    'cache --> db',
    'auth -> db',
    'db -> db-self',
    'db-self -> db   # binary cycle',
    'a1 -> b1 -> c1 -> d1',
    'z1->y1',
    'ghost only right -> rightmost',
    'no-edges-1,no-edges-2',
  ].join('\n');
  await page.fill('#input', dirty);
  await page.click('#btn-analyze');
  await page.waitForTimeout(200);
  const stats2 = await page.$eval('#stats', e => e.textContent.replace(/\s+/g,' ').trim());
  console.log('dirty stats:', stats2);
  await page.click('.tab[data-tab="tab-cycles"]');
  const cyc2 = await page.$eval('#cycle-list', e => e.textContent.replace(/\s+/g,' ').trim().slice(0,160));
  console.log('dirty cycles:', cyc2);

  // 自测
  await page.click('#btn-selftest');
  await page.waitForTimeout(800);
  const summary = await page.$eval('#test-summary', e => e.textContent.trim());
  const fails = await page.$$eval('#test-output .test-case.fail', els => els.map(e => e.textContent.replace(/\s+/g,' ').trim()));
  console.log('selftest:', summary, 'fails:', fails.length);
  console.log('js errors:', errors.length ? errors.join('\n') : 'none');
  await browser.close();
})().catch(e => { console.error('FATAL', e.message); process.exit(2); });
